import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"New Tenant Setup Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"new-tenant-setup.md","filePath":"new-tenant-setup.md"}'),o={name:"new-tenant-setup.md"};function n(l,e,r,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="new-tenant-setup-checklist" tabindex="-1">New Tenant Setup Checklist <a class="header-anchor" href="#new-tenant-setup-checklist" aria-label="Permalink to &quot;New Tenant Setup Checklist&quot;">​</a></h1><p>Complete every step in order. Missing any one of these will cause silent failures that are hard to diagnose after the fact.</p><hr><h2 id="_1-google-cloud-—-service-account" tabindex="-1">1. Google Cloud — Service Account <a class="header-anchor" href="#_1-google-cloud-—-service-account" aria-label="Permalink to &quot;1. Google Cloud — Service Account&quot;">​</a></h2><ul><li>[ ] Open <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">Google Cloud Console</a> → <strong>IAM &amp; Admin → Service Accounts</strong></li><li>[ ] Create a new service account (e.g. <code>vera-&lt;tenant-name&gt;@your-project.iam.gserviceaccount.com</code>)</li><li>[ ] Create a JSON key for the service account → download it</li><li>[ ] Copy the entire JSON contents — this becomes <code>google_credentials_json</code> in the tenant config</li></ul><hr><h2 id="_2-google-sheets-—-database-sheet" tabindex="-1">2. Google Sheets — Database Sheet <a class="header-anchor" href="#_2-google-sheets-—-database-sheet" aria-label="Permalink to &quot;2. Google Sheets — Database Sheet&quot;">​</a></h2><ul><li>[ ] Make a copy of the VERA database template spreadsheet (or create one from scratch using the header rows in <code>CLAUDE.md</code>)</li><li>[ ] Share the database sheet with the service account email as <strong>Editor</strong></li><li>[ ] Copy the spreadsheet ID from the URL (<code>/d/&lt;ID&gt;/edit</code>) → this becomes <code>google_sheet_id</code></li><li>[ ] Confirm all 14 tabs exist with correct names (<code>01. Time Entries</code> … <code>14. Liabilities</code>)</li><li>[ ] <strong>Do not share this spreadsheet with the client</strong> — it is bot-only</li></ul><hr><h2 id="_3-google-sheets-—-reporting-sheet-optional-but-recommended" tabindex="-1">3. Google Sheets — Reporting Sheet (optional but recommended) <a class="header-anchor" href="#_3-google-sheets-—-reporting-sheet-optional-but-recommended" aria-label="Permalink to &quot;3. Google Sheets — Reporting Sheet (optional but recommended)&quot;">​</a></h2><ul><li>[ ] Create a separate Google Sheets file owned by you</li><li>[ ] Add hidden mirror sheets for each database tab using <code>IMPORT_DB()</code> formulas (see <code>CLAUDE.md</code> for exact formulas)</li><li>[ ] Build visible dashboard tabs on top (see <code>CLAUDE.md</code> for tab list and column headers)</li><li>[ ] Share the reporting sheet with the client as <strong>Viewer</strong></li><li>[ ] The service account does NOT need access to this sheet</li></ul><hr><h2 id="_4-slack-—-create-a-slack-app" tabindex="-1">4. Slack — Create a Slack App <a class="header-anchor" href="#_4-slack-—-create-a-slack-app" aria-label="Permalink to &quot;4. Slack — Create a Slack App&quot;">​</a></h2><ul><li>[ ] Go to <a href="https://api.slack.com/apps" target="_blank" rel="noreferrer">api.slack.com/apps</a> → <strong>Create New App → From Manifest</strong></li><li>[ ] Paste the app manifest (Socket Mode enabled, required scopes below)</li><li>[ ] Under <strong>OAuth &amp; Permissions</strong>, install the app to the workspace</li><li>[ ] Copy the <strong>Bot User OAuth Token</strong> (<code>xoxb-...</code>) → <code>slack_bot_token</code></li><li>[ ] Under <strong>Basic Information → App-Level Tokens</strong>, create a token with <code>connections:write</code> scope → <code>slack_app_token</code> (<code>xapp-...</code>)</li></ul><p><strong>Required Bot Token Scopes:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>channels:history, channels:read, chat:write, files:write,</span></span>
<span class="line"><span>groups:history, im:history, im:read, im:write,</span></span>
<span class="line"><span>mpim:history, users:read, users:read.email</span></span></code></pre></div><hr><h2 id="_5-slack-—-audit-channel" tabindex="-1">5. Slack — Audit Channel <a class="header-anchor" href="#_5-slack-—-audit-channel" aria-label="Permalink to &quot;5. Slack — Audit Channel&quot;">​</a></h2><blockquote><p>⚠️ <strong>The bot must be explicitly invited to the audit channel.</strong> It cannot post to channels it has not joined, and failures are silent.</p></blockquote><ul><li>[ ] Create or identify the audit channel (e.g. <code>#vera-audit</code>) — can be private</li><li>[ ] Copy the channel ID (click the channel name → <strong>About</strong> → copy the ID starting with <code>C</code>) → <code>slack_audit_channel_id</code></li><li>[ ] <strong>Invite the bot to the channel</strong>: go to the channel → type <code>/invite @VERA</code> (or whatever your bot&#39;s display name is)</li><li>[ ] Verify: after setup, trigger a test write (e.g. log a time entry) and confirm a message appears in the channel</li></ul><hr><h2 id="_6-tenant-config-—-add-to-tenants-dev-json" tabindex="-1">6. Tenant Config — Add to <code>tenants.dev.json</code> <a class="header-anchor" href="#_6-tenant-config-—-add-to-tenants-dev-json" aria-label="Permalink to &quot;6. Tenant Config — Add to \`tenants.dev.json\`&quot;">​</a></h2><p>Add a new entry to the tenants file:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acme&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slack_bot_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xoxb-...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slack_app_token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xapp-...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;google_sheet_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1ABC...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;google_credentials_json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">type</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">service_account</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,...}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;timezone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;America/New_York&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slack_audit_channel_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C08ABC123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Field notes:</strong></p><ul><li><code>id</code> — short slug, lowercase, no spaces. Used in logs and internal routing.</li><li><code>timezone</code> — IANA format (e.g. <code>America/New_York</code>, <code>Europe/London</code>). Controls morning/evening reminder times and snapshot scheduling.</li><li><code>slack_audit_channel_id</code> — must be the channel <strong>ID</strong> (starts with <code>C</code>), not the channel name.</li><li><code>google_credentials_json</code> — paste the full JSON as a string (escape inner quotes). In Railway, set as an env var and reference it.</li></ul><hr><h2 id="_7-bootstrap-the-database-sheet" tabindex="-1">7. Bootstrap the Database Sheet <a class="header-anchor" href="#_7-bootstrap-the-database-sheet" aria-label="Permalink to &quot;7. Bootstrap the Database Sheet&quot;">​</a></h2><ul><li>[ ] In the database sheet, add the header row to each tab (copy from <code>CLAUDE.md</code> schema tables)</li><li>[ ] Leave all data rows empty — VERA will populate them as users interact</li><li>[ ] Do NOT manually enter data with different column positions — column order is a code contract</li></ul><p><strong>Minimum bootstrap data to create via VERA before going live:</strong></p><ol><li>At least one Owner user: tell VERA <code>&quot;add user [Name] as owner with Slack ID [U...]&quot;</code></li><li>At least one discipline: <code>&quot;add discipline Design with 8 hours per day&quot;</code></li><li>An Out of Office project (for PTO/sick leave): <code>&quot;create a project called Out of Office as Pro Bono, internal category, for client Internal&quot;</code></li><li>At least one task: <code>&quot;create a task called Development&quot;</code></li></ol><hr><h2 id="_8-smoke-test" tabindex="-1">8. Smoke Test <a class="header-anchor" href="#_8-smoke-test" aria-label="Permalink to &quot;8. Smoke Test&quot;">​</a></h2><p>Run through these in the new tenant&#39;s Slack workspace:</p><ul><li>[ ] Send <code>my id</code> in a DM to the bot → confirms bot is online and responding</li><li>[ ] <code>&quot;add user [yourself] as owner&quot;</code> → check <code>03. Users</code> sheet row was created</li><li>[ ] <code>&quot;log 1h on [project] for development&quot;</code> → check <code>01. Time Entries</code> row was created with correct columns A–H</li><li>[ ] Check the audit channel → should show the <code>log_time</code> audit entry</li><li>[ ] <code>&quot;!test morning&quot;</code> → should send the morning summary DM</li></ul><p>If the audit channel shows nothing after <code>log_time</code>, the bot has not been invited (step 5). Run <code>/invite @[botname]</code> in the audit channel and retry.</p><hr><h2 id="_9-railway-deployment-production" tabindex="-1">9. Railway Deployment (production) <a class="header-anchor" href="#_9-railway-deployment-production" aria-label="Permalink to &quot;9. Railway Deployment (production)&quot;">​</a></h2><ul><li>[ ] Add a new env var set in Railway for this tenant (or update <code>TENANTS_FILE</code> to point to a production tenants file)</li><li>[ ] For <code>google_credentials_json</code>, store as a Railway env var and reference it in the tenants JSON as <code>&quot;google_credentials_json&quot;: &quot;$TENANT_ACME_GOOGLE_CREDS&quot;</code> — do not commit raw service account keys to git</li><li>[ ] Redeploy and re-run the smoke test against the production Railway URL</li></ul><hr><h2 id="_10-postgres-migration-—-required-before-the-dashboard-works" tabindex="-1">10. Postgres Migration — required before the dashboard works <a class="header-anchor" href="#_10-postgres-migration-—-required-before-the-dashboard-works" aria-label="Permalink to &quot;10. Postgres Migration — required before the dashboard works&quot;">​</a></h2><p>The bot operates on Sheets, but the client dashboard reads from Postgres. A new tenant has zero rows in pg until you allowlist them and run the backfill. Skipping this step makes the dashboard return &quot;No active projects&quot; even though the bot is fully functional.</p><ul><li>[ ] Add the tenant id to the <code>PG_SHADOW_WRITE_TENANTS</code> env var on Railway (comma-separated, alongside any existing ids)</li><li>[ ] Run the one-time backfill from the live container — copies Sheets rows into Postgres:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>railway ssh --service VERA &quot;node scripts/backfill-tenant.js --tenant=&lt;tenant_id&gt; --dry-run&quot;</span></span></code></pre></div>Confirm the row counts look reasonable (users, clients, projects, time_entries all &gt; 0 unless the tenant is brand new).</li><li>[ ] Run the real backfill (drop <code>--dry-run</code>):<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>railway ssh --service VERA &quot;node scripts/backfill-tenant.js --tenant=&lt;tenant_id&gt;&quot;</span></span></code></pre></div>The script uses <code>ON CONFLICT DO UPDATE</code> and is idempotent — safe to re-run.</li><li>[ ] <strong>Restart the VERA service.</strong> <code>lib/dal.js</code> reads <code>PG_SHADOW_WRITE_TENANTS</code> once at module load — env-var changes are not picked up until the process restarts.</li><li>[ ] Verify: send a message to the bot from the new tenant and confirm it still works (sanity check that the pg flip didn&#39;t break anything for the tenant).</li></ul><hr><h2 id="_11-client-dashboard-—-vanity-url" tabindex="-1">11. Client Dashboard — vanity URL <a class="header-anchor" href="#_11-client-dashboard-—-vanity-url" aria-label="Permalink to &quot;11. Client Dashboard — vanity URL&quot;">​</a></h2><p>The client-facing dashboard is at <code>https://dash.getvera.site/d/&lt;slug&gt;</code>. The slug doubles as the secret — it routes and authenticates in a single segment.</p><ul><li>[ ] Open <code>/admin</code> and find the tenant</li><li>[ ] Click <strong>Generate</strong> next to <code>dashboard_slug</code> (or set a 12-character base62 string manually — ~71 bits entropy)</li><li>[ ] Save</li><li>[ ] Open <code>https://dash.getvera.site/d/&lt;slug&gt;</code> in an incognito window — should render the project list</li><li>[ ] If the page renders &quot;Dashboard not yet available&quot;, step 10 is incomplete (the tenant isn&#39;t pg-allowlisted, isn&#39;t backfilled, or the service hasn&#39;t been restarted)</li><li>[ ] Share the URL with the client</li></ul><p>The legacy URL <code>/report/&lt;tenant_id&gt;/dashboard</code> with <code>?token=&lt;client_report_token&gt;</code> still works for backwards compatibility, but prefer the vanity URL for new tenants.</p>`,48)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
